function mostExpensiveItem(primeOne, primeTwo) {
  // Mark every price up to the product that some coin total reaches, then take the highest unmarked one.
  const limit = primeOne * primeTwo;
  const reachable = new Array(limit + 1).fill(false);
  reachable[0] = true;
  let best = 0;
  for (let price = 1; price <= limit; price++) {
    reachable[price] = (price >= primeOne && reachable[price - primeOne]) || (price >= primeTwo && reachable[price - primeTwo]);
    if (!reachable[price]) best = price;
  }
  return best;
}

