function generate(rand, size) {
  const primes = [];
  const composite = new Array(10000).fill(false);
  for (let i = 2; i < 10000; i++) {
    if (composite[i]) continue;
    primes.push(i);
    for (let j = i * i; j < 10000; j += i) composite[j] = true;
  }
  const pick = list => list[Math.floor(rand() * list.length)];
  let one, two;
  if (size === 'large') {
    // A product close to the limit of 10^5; from 7 upwards every prime has such a partner below 10^4.
    one = pick(primes.filter(p => p >= 7 && p < 316));
    two = pick(primes.filter(p => p !== one && p * one < 100000 && p * one > 50000));
  } else {
    const small = primes.filter(p => p < 30);
    one = pick(small);
    two = pick(small.filter(p => p !== one));
  }
  return rand() < 0.5 ? [one, two] : [two, one];
}
